/* shipset.js: the single list of source files the build ships (used by verify/run.js, build.py and tools/verify_release.js).
 * GENERATED files are written ONLY by build.py into the out-of-tree artifact (never into the tracked tree). */
const fs = require('fs'), path = require('path'), crypto = require('crypto');
const STATIC = ['index.html', 'manifest.json', 'styles.css', 'sw.js', 'packs/confirmed_shared/index.json', 'packs/confirmed_shared/a.json', 'packs/confirmed_shared/b.json', 'packs/confirmed_shared/c.json', 'packs/confirmed_shared/d.json', 'packs/confirmed_shared/e.json', 'packs/confirmed_shared/f.json', 'packs/confirmed_shared/g.json', 'packs/confirmed_shared/h.json', 'packs/confirmed_shared/i.json', 'packs/confirmed_shared/j.json', 'packs/confirmed_shared/k.json', 'packs/confirmed_shared/l.json', 'packs/confirmed_shared/m.json', 'packs/confirmed_shared/n.json', 'packs/confirmed_shared/o.json', 'packs/confirmed_shared/p.json', 'packs/confirmed_shared/q.json', 'packs/confirmed_shared/r.json', 'packs/confirmed_shared/s.json', 'packs/confirmed_shared/t.json', 'packs/confirmed_shared/u.json', 'packs/confirmed_shared/v.json', 'packs/confirmed_shared/w.json', 'packs/confirmed_shared/x.json', 'packs/confirmed_shared/y.json', 'packs/confirmed_shared/z.json', 'data/anchors_187.json', 'data/lexicon.json.gz', 'data/lexicon-ext.json.gz', 'data/lexicon-pro.json.gz', 'data/WORDNET_LICENSE.txt', 'data/SBOM.json', 'data/command_catalog.json', 'data/feature_registry.json', 'data/py/coherence_math.py', 'data/py/rmc_engine_bundle.json', 'icons/icon-192.png', 'icons/icon-512.png', 'vendor/three.module.min.js', 'vendor/cannon-es.js', 'vendor/LICENSE.three.txt', 'vendor/LICENSE.cannon-es.txt'];
const GENERATED = ['src/build-info.js', 'src/release.js', 'src/features.js', 'build-info.json', 'BUILD_MANIFEST.json'];
function list(root) { return STATIC.concat(fs.readdirSync(path.join(root, 'src')).filter(f => f.endsWith('.js') && !GENERATED.includes('src/' + f)).sort().map(f => 'src/' + f)); }
/* hash of every input that shapes the shipped app plus the verifier itself: build.py refuses to build a tree that verification did not see */
function inputs(root) { const v = fs.readdirSync(path.join(root, 'verify')).filter(f => f.endsWith('.js')).sort().map(f => 'verify/' + f); return list(root).concat(v, ['VERSION', 'build.py', 'tools/shipset.js']); }
function treeHash(root) { const h = crypto.createHash('sha256'); for (const f of inputs(root)) h.update(f + '\0' + crypto.createHash('sha256').update(fs.readFileSync(path.join(root, f))).digest('hex') + '\n'); return h.digest('hex'); }
module.exports = { STATIC, GENERATED, list, inputs, treeHash };
if (require.main === module) { const root = path.join(__dirname, '..'); if (process.argv[2] === 'hash') process.stdout.write(treeHash(root)); else process.stdout.write(JSON.stringify(list(root))); }
